const config = {
  "previewFeatures": [],
  "clientVersion": "7.9.1",
  "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
  "activeProvider": "sqlite",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n}\n\n// -----------------------------------------\n// USERS & ACCOUNTS (NextAuth)\n// -----------------------------------------\nmodel User {\n  id            Int       @id @default(autoincrement())\n  name          String? // NextAuth uses this\n  username      String?   @unique // Minecraft Nickname\n  email         String?   @unique\n  emailVerified DateTime? // NextAuth uses this\n  password      String?\n  image         String? // NextAuth uses this\n  role          String    @default(\"USER\") // USER, ADMIN, MODERATOR\n  balance       Float     @default(0.0) // Virtual Coins\n  avatar        String?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  accounts          Account[]\n  sessions          Session[]\n  orders            Order[]\n  tickets           Ticket[]\n  ticketReplies     TicketReply[]\n  posts             BlogPost[]\n  forumTopics       ForumTopic[]\n  forumReplies      ForumReply[]\n  fortuneHistory    FortuneWheelHistory[]\n  chestItems        ChestItem[]\n  giftCardsRedeemed GiftCard[]\n  suggestions       Suggestion[]\n  suggestionVotes   SuggestionVote[]\n  creatorCodes      CreatorCode[]\n}\n\nmodel Account {\n  id                Int     @id @default(autoincrement())\n  userId            Int\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String?\n  access_token      String?\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String?\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n}\n\nmodel Session {\n  id           Int      @id @default(autoincrement())\n  sessionToken String   @unique\n  userId       Int\n  expires      DateTime\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n}\n\n// -----------------------------------------\n// STORE (Loja)\n// -----------------------------------------\nmodel Category {\n  id          Int      @id @default(autoincrement())\n  name        String\n  slug        String   @unique\n  description String?\n  icon        String? // Icon name\n  order       Int      @default(0)\n  isHidden    Boolean  @default(false)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  products Product[]\n  coupons  Coupon[]\n}\n\nmodel Product {\n  id                 Int      @id @default(autoincrement())\n  name               String\n  description        String\n  price              Float\n  imageUrl           String?\n  categoryId         Int\n  category           Category @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n  isFeatured         Boolean  @default(false)\n  isHidden           Boolean  @default(false)\n  showInVipTable     Boolean  @default(false)\n  command            String?\n  discountPercentage Int?\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n\n  orderItems       OrderItem[]\n  coupons          Coupon[]\n  vipFeatureValues ProductVipFeatureValue[]\n}\n\nmodel Coupon {\n  id          Int       @id @default(autoincrement())\n  code        String    @unique\n  discountPct Int\n  maxUses     Int?\n  uses        Int       @default(0)\n  expiresAt   DateTime?\n  isActive    Boolean   @default(true)\n  createdAt   DateTime  @default(now())\n\n  orders     Order[]\n  categories Category[]\n  products   Product[]\n}\n\nmodel GiftCard {\n  id        Int       @id @default(autoincrement())\n  code      String    @unique\n  amount    Float // Amount of balance this card gives\n  isUsed    Boolean   @default(false)\n  usedById  Int?\n  usedBy    User?     @relation(fields: [usedById], references: [id])\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n}\n\nmodel Order {\n  id            Int          @id @default(autoincrement())\n  userId        Int?\n  user          User?        @relation(fields: [userId], references: [id])\n  player        String // Nick do jogador\n  total         Float\n  status        String       @default(\"PENDING\") // PENDING, PAID, CANCELLED\n  couponId      Int?\n  coupon        Coupon?      @relation(fields: [couponId], references: [id])\n  creatorCodeId Int?\n  creatorCode   CreatorCode? @relation(fields: [creatorCodeId], references: [id])\n  createdAt     DateTime     @default(now())\n  updatedAt     DateTime     @updatedAt\n\n  items OrderItem[]\n}\n\nmodel CreatorCode {\n  id              Int      @id @default(autoincrement())\n  code            String   @unique\n  discountPercent Int\n  rewardPercent   Int\n  creatorId       Int\n  creator         User     @relation(fields: [creatorId], references: [id])\n  uses            Int      @default(0)\n  totalGenerated  Float    @default(0.0) // Total value generated for the store\n  totalRewarded   Float    @default(0.0) // Total balance given to the creator\n  isActive        Boolean  @default(true)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  orders Order[]\n}\n\nmodel OrderItem {\n  id        Int     @id @default(autoincrement())\n  orderId   Int\n  order     Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  productId Int\n  product   Product @relation(fields: [productId], references: [id])\n  quantity  Int     @default(1)\n  price     Float\n}\n\n// -----------------------------------------\n// TICKETS (Suporte)\n// -----------------------------------------\nmodel Ticket {\n  id        Int      @id @default(autoincrement())\n  title     String\n  status    String   @default(\"OPEN\") // OPEN, ANSWERED, CLOSED\n  userId    Int\n  user      User     @relation(fields: [userId], references: [id])\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  replies TicketReply[]\n}\n\nmodel TicketReply {\n  id        Int      @id @default(autoincrement())\n  content   String\n  ticketId  Int\n  ticket    Ticket   @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n  userId    Int\n  user      User     @relation(fields: [userId], references: [id])\n  createdAt DateTime @default(now())\n}\n\n// -----------------------------------------\n// BLOG (Notícias)\n// -----------------------------------------\nmodel BlogPost {\n  id        Int      @id @default(autoincrement())\n  title     String\n  slug      String   @unique\n  content   String\n  imageUrl  String?\n  authorId  Int\n  author    User     @relation(fields: [authorId], references: [id])\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// -----------------------------------------\n// FORUM\n// -----------------------------------------\nmodel ForumCategory {\n  id          Int          @id @default(autoincrement())\n  name        String\n  description String?\n  icon        String?\n  order       Int          @default(0)\n  topics      ForumTopic[]\n}\n\nmodel ForumTopic {\n  id         Int           @id @default(autoincrement())\n  title      String\n  content    String\n  categoryId Int\n  category   ForumCategory @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n  authorId   Int\n  author     User          @relation(fields: [authorId], references: [id])\n  views      Int           @default(0)\n  isPinned   Boolean       @default(false)\n  isLocked   Boolean       @default(false)\n  createdAt  DateTime      @default(now())\n  updatedAt  DateTime      @updatedAt\n\n  replies ForumReply[]\n}\n\nmodel ForumReply {\n  id        Int        @id @default(autoincrement())\n  content   String\n  topicId   Int\n  topic     ForumTopic @relation(fields: [topicId], references: [id], onDelete: Cascade)\n  authorId  Int\n  author    User       @relation(fields: [authorId], references: [id])\n  createdAt DateTime   @default(now())\n  updatedAt DateTime   @updatedAt\n}\n\n// -----------------------------------------\n// PUNISHMENTS (Bans/Mutes)\n// -----------------------------------------\nmodel Punishment {\n  id        Int       @id @default(autoincrement())\n  type      String // BAN, MUTE, WARN, KICK\n  player    String\n  operator  String\n  reason    String\n  expiresAt DateTime?\n  createdAt DateTime  @default(now())\n}\n\n// -----------------------------------------\n// SUGGESTIONS (Módulo)\n// -----------------------------------------\nmodel Suggestion {\n  id        Int      @id @default(autoincrement())\n  title     String\n  content   String\n  status    String   @default(\"PENDING\") // PENDING, APPROVED, REJECTED, IMPLEMENTED\n  authorId  Int\n  author    User     @relation(fields: [authorId], references: [id])\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  votes SuggestionVote[]\n}\n\nmodel SuggestionVote {\n  id           Int        @id @default(autoincrement())\n  suggestionId Int\n  suggestion   Suggestion @relation(fields: [suggestionId], references: [id], onDelete: Cascade)\n  userId       Int\n  user         User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  isUpvote     Boolean // true = upvote, false = downvote\n  createdAt    DateTime   @default(now())\n\n  @@unique([suggestionId, userId])\n}\n\n// -----------------------------------------\n// ACCESS TOKENS (Team/Admin)\n// -----------------------------------------\nmodel AccessToken {\n  id        Int      @id @default(autoincrement())\n  name      String\n  token     String   @unique\n  isValid   Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// -----------------------------------------\n// SETTINGS (Configurações Gerais)\n// -----------------------------------------\nmodel Setting {\n  key       String   @id // ex: \"WHEEL_COST\", \"WHEEL_COOLDOWN_MINUTES\"\n  value     String\n  updatedAt DateTime @updatedAt\n}\n\n// -----------------------------------------\n// FORTUNE WHEEL (Roleta)\n// -----------------------------------------\nmodel FortuneWheelItem {\n  id        Int      @id @default(autoincrement())\n  name      String\n  type      String // CREDITS, COMMAND, EMPTY\n  value     String? // amount of credits or the command string\n  weight    Int      @default(10) // probability weight\n  color     String   @default(\"#000000\") // hex color\n  icon      String? // lucide icon name\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  history FortuneWheelHistory[]\n}\n\nmodel FortuneWheelHistory {\n  id        Int              @id @default(autoincrement())\n  userId    Int\n  user      User             @relation(fields: [userId], references: [id], onDelete: Cascade)\n  itemId    Int\n  item      FortuneWheelItem @relation(fields: [itemId], references: [id], onDelete: Cascade)\n  createdAt DateTime         @default(now())\n}\n\n// -----------------------------------------\n// CHEST (Baú do Jogador)\n// -----------------------------------------\nmodel ChestItem {\n  id     Int  @id @default(autoincrement())\n  userId Int\n  user   User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  name        String\n  description String?\n  imageUrl    String?\n  command     String? // Comando do produto ou da roleta\n  type        String // \"PRODUCT\", \"CREDITS\", \"COMMAND\"\n  amount      Float? // Usado caso seja um prémio de créditos (saldo)\n  source      String // \"STORE\", \"FORTUNE_WHEEL\", \"ADMIN\"\n\n  status     String    @default(\"PENDING\") // PENDING, REDEEMED\n  redeemedAt DateTime?\n  redeemedBy String? // O nick do jogador que recebeu o item/comando (para onde foi resgatado/enviado)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// -----------------------------------------\n// DOWNLOADS\n// -----------------------------------------\nmodel DownloadItem {\n  id          Int      @id @default(autoincrement())\n  name        String\n  slug        String   @unique\n  description String\n  downloadUrl String\n  imageUrl    String? // Link para a imagem (ex: capa do modpack)\n  icon        String? // lucide icon name\n  downloads   Int      @default(0)\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\n// -----------------------------------------\n// VIP TABLE (Tabela de VIPs)\n// -----------------------------------------\nmodel VipFeature {\n  id          Int     @id @default(autoincrement())\n  name        String\n  description String?\n  group       String  @default(\"Geral\")\n  order       Int     @default(0)\n\n  productValues ProductVipFeatureValue[]\n}\n\nmodel ProductVipFeatureValue {\n  id        Int        @id @default(autoincrement())\n  productId Int\n  product   Product    @relation(fields: [productId], references: [id], onDelete: Cascade)\n  featureId Int\n  feature   VipFeature @relation(fields: [featureId], references: [id], onDelete: Cascade)\n\n  type         String  @default(\"BOOLEAN\") // BOOLEAN, TEXT\n  booleanValue Boolean @default(false)\n  textValue    String?\n\n  @@unique([productId, featureId])\n}\n\n// -----------------------------------------\n// VOTE SITES (Votos)\n// -----------------------------------------\nmodel VoteSite {\n  id        Int      @id @default(autoincrement())\n  name      String\n  url       String\n  imageUrl  String?\n  reward    String?\n  order     Int      @default(0)\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// -----------------------------------------\n// CUSTOM PAGES (Páginas Personalizadas)\n// -----------------------------------------\nmodel CustomPage {\n  id        Int      @id @default(autoincrement())\n  title     String\n  slug      String   @unique\n  content   String\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// -----------------------------------------\n// NAVIGATION (Menu de Navegação)\n// -----------------------------------------\nmodel NavigationItem {\n  id        Int      @id @default(autoincrement())\n  label     String\n  url       String\n  icon      String?\n  order     Int      @default(0)\n  isActive  Boolean  @default(true)\n  isSystem  Boolean  @default(false)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n"
}

